--
-- Table structure for table `offers`
--

DROP TABLE IF EXISTS `offers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `offers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `partner_id` int(11) DEFAULT NULL,
  `offer_for` varchar(256) DEFAULT NULL,
  `offerred_by` varchar(256) DEFAULT NULL,
  `identity` varchar(256) DEFAULT NULL,
  `function` varchar(256) DEFAULT NULL,
  `title` varchar(256) DEFAULT NULL,
  `discount` varchar(256) DEFAULT NULL,
  `deal_amount` varchar(256) DEFAULT NULL,
  `incentive` varchar(256) DEFAULT NULL,
  `available_in` varchar(256) DEFAULT NULL,
  `currency` varchar(256) DEFAULT NULL,
  `weblink` varchar(256) DEFAULT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'On',
  `admin_status` tinyint(4) NOT NULL DEFAULT 0,
  `share_id` varchar(256) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

