--
-- Table structure for table `response_bids`
--

DROP TABLE IF EXISTS `response_bids`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `response_bids` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `respond_user_id` int(11) NOT NULL,
  `bid_id` int(11) NOT NULL,
  `description` text NOT NULL,
  `portfolio_link` varchar(256) NOT NULL,
  `is_spam` tinyint(4) NOT NULL DEFAULT 0,
  `is_counted` tinyint(4) NOT NULL DEFAULT 0,
  `spam_reason` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `is_accepted` tinyint(4) NOT NULL DEFAULT 0 COMMENT '1=read more,2=accepted',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=86 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

